      !>                  WRITE (*,*) '    d Q(1)/dt: ', RECORD(9)
      !>                  WRITE (*,*) '    d Q(2)/dt: ', RECORD(10)
      !>                  WRITE (*,*) '    d Q(3)/dt: ', RECORD(11)
      !>
      !>               ELSE IF ( SUBTYP .EQ. C06TP1 ) THEN
      !>
