      !>
      !>               ELSE IF ( SUBTYP .EQ. C06TP2 ) THEN
      !>
      !>                  WRITE (*,*) '         Q(0): ', RECORD(4)
      !>                  WRITE (*,*) '         Q(1): ', RECORD(5)
      !>                  WRITE (*,*) '         Q(2): ', RECORD(6)
