      !>                  WRITE (*,*) '   d AV(2)/dt: ', RECORD(16)
      !>                  WRITE (*,*) '   d AV(3)/dt: ', RECORD(17)
      !>
      !>               ELSE IF ( SUBTYP .EQ. C06TP3 ) THEN
      !>
      !>                  WRITE (*,*) '         Q(0): ', RECORD(4)
      !>                  WRITE (*,*) '         Q(1): ', RECORD(5)
      !>                  WRITE (*,*) '         Q(2): ', RECORD(6)
      !>                  WRITE (*,*) '         Q(3): ', RECORD(7)
      !>                  WRITE (*,*) '        AV(1): ', RECORD(8)
      !>                  WRITE (*,*) '        AV(2): ', RECORD(9)
      !>                  WRITE (*,*) '        AV(3): ', RECORD(10)
      !>
      !>               ELSE
      !>                  CALL SETMSG ( 'Subtype # is not '
      !>     .            //            'recognized.'         )
      !>                  CALL ERRINT ( '#', SUBTYP           )
