      !>
      !>      CHARACTER*(*)         REF
      !>      PARAMETER           ( REF    = 'J2000'          )
      !>
      !>      DOUBLE PRECISION      GMSUN
      !>      PARAMETER           ( GMSUN  = 132712440023.310D0 )
