      !>      CHARACTER*(NAMLEN)    SEGID
      !>
      !>      DOUBLE PRECISION      EPOCHS (    NSTATS )
      !>      DOUBLE PRECISION      FIRST
      !>      DOUBLE PRECISION      LAST
      !>      DOUBLE PRECISION      STATES ( 6, NSTATS )
      !>
